import os
from google.cloud import logging

class ObservabilityClient:
    def __init__(self):
        # Google Cloud Project ID can be explicitly set or inferred from the environment
        project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
        self.logging_client = logging.Client(project=project_id)

    def get_logger(self, log_name: str):
        return self.logging_client.logger(log_name)

    def list_entries(self, filter_: str, order_by: str, page_size: int):
        return self.logging_client.list_entries(filter_=filter_, order_by=order_by, page_size=page_size)

from observability_client import ObservabilityClient
from observability_models import StructuredLogEntry

def write_structured_log(log_name: str, entry: StructuredLogEntry):
    client = ObservabilityClient()
    logger = client.get_logger(log_name)

    # Google Cloud Logging expects json_payload as a dict directly
    # and other fields like severity, resource, labels as separate arguments
    logger.log(
        text_payload=entry.message, # Use text_payload for the main message if json_payload is also present
        severity=entry.severity,
        resource=entry.resource,
        labels=entry.labels,
        json_payload=entry.json_payload # Structured data goes here
    )


if __name__ == "__main__":
    # Example Usage:
    log_entry = StructuredLogEntry(
        message="This is a test structured log entry.",
        severity="INFO",
        resource={
            "type": "global",
            "labels": {
                "project_id": "your-gcp-project-id" # Replace with your GCP Project ID
            },
        },
        labels={
            "environment": "development",
            "service": "my-app"
        },
        json_payload={
            "event_type": "user_action",
            "user_id": "12345",
            "action": "login",
            "details": {"ip_address": "192.168.1.1", "device": "mobile"}
        }
    )
    write_structured_log("my-application-logs", log_entry)

from datetime import datetime, timedelta
from typing import Dict, Any, Optional
from observability_client import ObservabilityClient
from observability_models import LogEntry

def fetch_recent_logs(
    log_name: Optional[str] = None,
    time_range_minutes: int = 60,
    field_filters: Optional[Dict[str, str]] = None
) -> list[LogEntry]:
    client = ObservabilityClient()

    now = datetime.utcnow()
    time_filter_iso = (now - timedelta(minutes=time_range_minutes)).isoformat('T', 'milliseconds') + 'Z'

    filters: list[str] = [f'timestamp>="{time_filter_iso}'
    ]

    if log_name:
        filters.append(f'logName="projects/{{your-gcp-project-id}}/logs/{log_name}'
        ) # Replace with your GCP Project ID environment variable if needed

    if field_filters:
        for field, value in field_filters.items():
            # This is a simplified filtering. For more complex filters (e.g., nested JSON fields),
            # the filter string might need to be constructed more carefully based on Cloud Logging syntax.
            filters.append(f'{field}="{value}'
            )

    filter_string = " AND ".join(filters)

    entries_iterator = client.list_entries(filter_=filter_string, order_by="timestamp desc", page_size=100)

    recent_logs: list[LogEntry] = []
    for entry in entries_iterator:
        json_payload = None
        message = ""
        if entry.payload_type == 'json':
            json_payload = entry.json_payload
            message = json_payload.get("message", "")
        elif entry.payload_type == 'text':
            json_payload = {"message": entry.text_payload}
            message = entry.text_payload
        elif entry.payload_type == 'proto':
            json_payload = {"message": str(entry.proto_payload)}
            message = str(entry.proto_payload)

        recent_logs.append(LogEntry(
            timestamp=entry.timestamp.isoformat(),
            severity=entry.severity,
            message=message,
            resource_type=entry.resource.type if entry.resource else "unknown",
            resource_labels=entry.resource.labels if entry.resource else {},
            json_payload=json_payload
        ))
    return recent_logs

if __name__ == "__main__":
    # Example Usage: Fetch logs from 'my-application-logs' for the last 60 minutes
    # and filter by a specific service label.

    # Ensure to set GOOGLE_CLOUD_PROJECT_ID environment variable or replace '{{your-gcp-project-id}}' 
    # in the logName filter string with your actual project ID.

    # Example 1: Fetch all recent logs for a specific log name
    print("\n--- Fetching all logs from 'my-application-logs' in last 60 minutes ---")
    logs_from_app = fetch_recent_logs(log_name="my-application-logs", time_range_minutes=60)
    for log in logs_from_app:
        print(f"[{log.timestamp}] {log.severity}: {log.message}")

    # Example 2: Fetch recent logs with a specific field filter
    print("\n--- Fetching logs with 'service=my-app' label in last 60 minutes ---")
    filtered_logs = fetch_recent_logs(
        time_range_minutes=60,
        field_filters={
            "resource.labels.service": "my-app" # Example of filtering by resource label
        }
    )
    for log in filtered_logs:
        print(f"[{log.timestamp}] {log.severity}: {log.message} (Resource Labels: {log.resource_labels})")

import os
from google.cloud import translate_v2 as translate

def translate_log_message(text: str, target_language: str = "es") -> dict:
    # Configure the Google Cloud Translation client
    # Ensure GOOGLE_APPLICATION_CREDENTIALS is set or project ID is configured.
    translate_client = translate.Client()

    if not text:
        return {"translated_text": "", "detected_source_language": ""}

    try:
        result = translate_client.translate(
            text,
            target_language=target_language
        )

        return {
            "translated_text": result['translatedText'],
            "detected_source_language": result['detectedSourceLanguage']
        }
    except Exception as e:
        return {"error": f"Error translating log message: {e}"}

if __name__ == "__main__":
    # Example Usage:
    log_message_en = "User login failed due to invalid credentials."
    target_lang = "fr"

    print(f"Original (EN): {log_message_en}")
    translation_result = translate_log_message(log_message_en, target_lang)

    if "error" in translation_result:
        print(f"Error: {translation_result['error']}")
    else:
        print(f"Translated ({target_lang.upper()}): {translation_result['translated_text']}")
        print(f"Detected Source Language: {translation_result['detected_source_language']}")

    log_message_es = "Error en la base de datos: conexión perdida."
    target_lang_en = "en"

    print(f"\nOriginal (ES): {log_message_es}")
    translation_result_es = translate_log_message(log_message_es, target_lang_en)

    if "error" in translation_result_es:
        print(f"Error: {translation_result_es['error']}")
    else:
        print(f"Translated ({target_lang_en.upper()}): {translation_result_es['translated_text']}")
        print(f"Detected Source Language: {translation_result_es['detected_source_language']}")
